// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        // adversarial counterparty that only accepts exactly `amount` wei
        StrictReceiver r = (new StrictReceiver){value: amount}(c, amount);
        assertEq(c.balances(address(r)), amount, "deposit recorded");
        vm.prank(address(r));
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        // Reference always pays exactly the owed amount, so a callee accepting
        // only that exact amount lets withdraw succeed; the buggy version sends 0.
        assertTrue(ok, "withdraw must pay exactly the owed amount");
    }
}

contract StrictReceiver {
    keepMyEther t;
    uint256 amt;
    constructor(keepMyEther c_, uint256 a_) payable {
        t = c_;
        amt = a_;
        address(t).call{value: a_}("");
    }
    fallback() external payable {
        require(msg.value == amt);
    }
}
